import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Collectors;

public class Main {
    @FunctionalInterface
    interface MathOp {
        int apply(int a, int b);
        default String name() { return "math"; }
        static MathOp plus() { return (a, b) -> a + b; }
    }

    void run() {
        // --- 方法引用四种形式 ---
        Function<String, Integer> strLen = String::length;          // 实例方法，接收者作参数
        Supplier<List<String>> factory = ArrayList::new;             // 构造器引用
        Predicate<String> nonEmpty = String::isEmpty;                // 实例方法，等价于 s -> s.isEmpty() → 取反
        Predicate<String> notEmpty = s -> !s.isEmpty();

        // --- SAM 赋值和组合 ---
        MathOp add = MathOp.plus();
        MathOp multiply = (a, b) -> a * b;
        Comparator<String> cmp = Comparator.comparingInt(String::length)
                                           .thenComparing(Comparator.naturalOrder());

        // --- 有效捕获 ---
        String prefix = "hello ";   // effectively final
        Function<String, String> greeter = name -> prefix + name;
        // prefix = "changed";     // 取消注释会编译失败：variable used in lambda should be effectively final

        // --- this 差异验证 ---
        Object lambdaThis = ((Supplier<Object>) () -> this).get();
        Object anonymousThis = new Supplier<Object>() {
            public Object get() { return this; }
        }.get();

        // --- Stream 组合 ---
        List<String> names = factory.get();
        names.addAll(List.of("Bob", "Alice", "Charlie"));
        names.sort(cmp);
        List<String> upper = names.stream()
                                  .filter(notEmpty)
                                  .map(String::toUpperCase)
                                  .collect(Collectors.toList());

        // --- 输出验证 ---
        System.out.println("sum: " + add.apply(3, 5));
        System.out.println("multiply: " + multiply.apply(3, 5));
        System.out.println("strLen(Alice): " + strLen.apply("Alice"));
        System.out.println("sorted: " + names);
        System.out.println("upper: " + upper);
        System.out.println("greeter: " + greeter.apply("lambda"));
        System.out.println("lambda this == outer: " + (lambdaThis == this));
        System.out.println("anonymous this == outer: " + (anonymousThis == this));

        assert add.apply(3, 5) == 8;
        assert multiply.apply(3, 5) == 15;
        assert strLen.apply("Alice") == 5;
        assert upper.equals(List.of("BOB", "ALICE", "CHARLIE"));
        assert greeter.apply("world").equals("hello world");
        assert lambdaThis == this;          // Lambda 的 this 指向外层
        assert anonymousThis != this;       // 匿名内部类的 this 指向自己
    }

    public static void main(String[] args) {
        new Main().run();
    }
}
